<div class="mb-4"><a href="/app/utenti" class="text-decoration-none">← Torna agli utenti</a><h1 class="h2 mt-2"><?= $id?'Modifica account':'Aggiungi utente' ?></h1><p class="text-secondary mb-0">Il ruolo determina quali sezioni sono accessibili.</p></div><form method="post" action="/app/utenti<?= $id?'/'.(int)$id:'' ?>" class="card border-0 shadow-sm" style="max-width:850px"><div class="card-body p-4"><div class="row g-3"><?php foreach(['nome'=>'Nome','cognome'=>'Cognome','email'=>'Email','telefono'=>'Telefono'] as $k=>$label): ?><div class="col-md-6"><label class="form-label" for="<?= e($k) ?>"><?= e($label) ?><?= $k!=='telefono'?' *':'' ?></label><input class="form-control" id="<?= e($k) ?>" name="<?= e($k) ?>" value="<?= e($utente[$k]??'') ?>" <?= $k!=='telefono'?'required':'' ?> <?= $k==='email'?'type="email" autocomplete="email"':'' ?>></div><?php endforeach ?><div class="col-md-6"><label class="form-label" for="userRole">Ruolo *</label><select class="form-select" id="userRole" name="ruolo_id" required><?php foreach($ruoli as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (string)$r['id']===(string)($utente['ruolo_id']??'')?'selected':'' ?>><?= e($r['nome']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label" for="userPassword">Password <?= $id?'(lascia vuoto per non cambiarla)':'*' ?></label><input class="form-control" id="userPassword" type="password" name="password" <?= $id?'':'required' ?> minlength="12" autocomplete="new-password"><div class="help-text">Almeno 12 caratteri.</div></div><div class="col-12 form-check ms-2"><input class="form-check-input" id="userActive" type="checkbox" name="attivo" value="1" <?= ($utente['attivo']??1)?'checked':'' ?>><label class="form-check-label" for="userActive">Account attivo</label></div></div><?= $csrf->field() ?><div class="actions mt-4"><button class="btn btn-primary btn-lg">Salva utente</button><a class="btn btn-outline-secondary" href="/app/utenti">Annulla</a></div></div></form>
